; late.asm -- chapter 46: guards placed a loop late
; generated by gen46.py
        INCLUDE "msx.inc"
        OUTPUT "late.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
stat    EQU VARS                ; the status isr read: F, 5S, C, a sprite's number
ticks   EQU VARS + 1            ; frames counted by isr, two bytes
state   EQU VARS + 3            ; TITLE, PLAY, FLIP, MAP, HIT, OVER or WIN
held    EQU VARS + 4            ; the keys and the stick: a 0 for each held
was     EQU VARS + 5            ; held as the loop before found it
room    EQU VARS + 6            ; the room the explorer is in, 0 to 15
lives   EQU VARS + 7            ; the lives left
fresh   EQU VARS + 8            ; 1: the room just come into had not been seen
queued  EQU VARS + 9            ; the names queued for the sends
keepy   EQU VARS + 10           ; the explorer's Y while the map is shown
whole   EQU VARS + 11           ; 1: the sends send a whole page
wsrc    EQU VARS + 12           ; its rows 1 to 23, two bytes
wr3     EQU VARS + 14           ; and R#3 and R#4 to show it with
wr4     EQU VARS + 15
queue   EQU VARS + $10          ; 16 names: the VRAM address, then the name
copy    EQU VARS + $40          ; the sprites' attributes: Y, X, pattern, colour
explorer EQU copy               ; the explorer's,
guard0  EQU copy + 4            ; the room's two guards',
guard1  EQU copy + 8
gd      EQU VARS + $50          ; and the guards' rounds, four bytes each
due     EQU VARS + $58          ; lines owed to the game's steps, two bytes
nlit    EQU VARS + $5A          ; the lanterns lit, BCD
time    EQU VARS + $5B          ; the time: its hundreds, then a BCD pair
tock    EQU VARS + $5D          ; steps to the next unit of time
left    EQU VARS + $5E          ; the steps left of HIT, OVER or WIN
dimmed  EQU VARS + $5F          ; the rooms of the map unlit again at the end
back    EQU VARS + $60          ; where the explorer came into the room: Y, X
been    EQU VARS + $70          ; a byte a room: 1 when seen
lit     EQU VARS + $80          ; a byte a lantern: 1 when lit
score   EQU VARS + $A0          ; three BCD bytes (chapter 40)
hi      EQU score + 3           ; the best, three more
ENGINE  EQU $C000               ; chapter 37's player, in a page of its own:
beats   EQU ENGINE              ; its ticks, two bytes (chapter 37's ticks)
owed    EQU ENGINE + 2          ; lines owed to the player, two bytes
lines   EQU ENGINE + 4          ; the machine's lines a frame: 313 or 262
tick    EQU ENGINE + 6          ; ticks still to the next row
songp   EQU ENGINE + 7          ; the song's step, two bytes (chapter 37's step)
barno   EQU ENGINE + 9          ; the step's number
rowno   EQU ENGINE + 10         ; the row in the bar
shadow  EQU ENGINE + $20        ; R0 to R10, as the next tick sends them
chan_a  EQU shadow + 11         ; the channels, CHAN bytes each
chan_b  EQU chan_a + CHAN
chan_c  EQU chan_b + CHAN
chan_x  EQU chan_c + CHAN       ; the effect: a fourth channel, on C's registers
names   EQU $C400               ; the copy of the 768 names
mapn    EQU $C700               ; the map's page, rows 1 to 23
minis   EQU $CA00               ; the rooms' pictures, 96 bytes each
SSLOT   EQU $FFFF               ; the secondary slot register, in page 3
SAT     EQU $1B00               ; the sprites' attributes
SPAT    EQU $3800               ; and their patterns
TITLE   EQU 0                   ; the states
PLAY    EQU 1
FLIP    EQU 2
MAP     EQU 3
HIT     EQU 4
OVER    EQU 5
WIN     EQU 6
FLOOR   EQU 0                   ; the tiles' names: from BRICK up, a wall
FLAG    EQU 1
RUG     EQU 2
BRICK   EQU 3
STONE   EQU 4
LANTERN EQU 5
LIT     EQU 6                   ; a lantern lit
DARK    EQU 8                   ; the map's dark
DIGIT0  EQU $30                 ; '0': a digit's name is its code
CURRENT EQU 224                 ; the names of the explorer's room on the map
X_LAST  EQU 240                 ; the explorer's edges: X 0 to X_LAST,
Y_FIRST EQU 7                   ; Y Y_FIRST to Y_LAST
Y_LAST  EQU 175
WAY_N   EQU 0                   ; the ways out
WAY_E   EQU 1
WAY_S   EQU 2
WAY_W   EQU 3
START   EQU 13                  ; the gate hall
STEPL   EQU 262                 ; the lines of a step: the 60 Hz frame
GAME_R3 EQU $9F               ; R#3 and R#4 of the play: one set for three thirds
GAME_R4 EQU $00
MAP_R3  EQU $FF               ; and of the map: a set for each
MAP_R4  EQU $03
LIVES   EQU 3
STILL   EQU 50                  ; steps held still at a touch
ENDS    EQU 150                 ; steps of the end
TICKS   EQU 16                  ; steps for each unit of time
LAMPS   EQU $32                 ; the lanterns, BCD
LIT_AT  EQU 5                   ; row 0: the lanterns lit,
LIVES_AT EQU 17                 ; the lives,
TIME_AT EQU 24                  ; the time
ROOM_AT EQU 29                  ; and the room's name
BOX_AT  EQU $1800 + 32 * 9 + 4  ; the end's box
SCORE_AT EQU $1800 + 32 * 12 + 11 ; and the score's digits in it,
HI_AT   EQU $1800 + 32 * 12 + 21 ; the best's,
THI_AT  EQU $1800 + 32 * 16 + 14 ; and the best's on the title
WAITS   EQU 0                   ; rows to wait; an effect: ticks to sound
NOTE    EQU 1                   ; the note, 0 for a rest
INSTR   EQU 2                   ; the instrument
PATTERN EQU 3                   ; the next event
VOLUME  EQU 5                   ; this tick's level in the volume table
PITCHES EQU 7                   ; this tick's semitones
FIRST   EQU 9                   ; the pitch table's first byte
MIXER   EQU 11                  ; the instrument's TONE and NOISE
NOISEP  EQU 12                  ; its noise's period
SHPER   EQU 13                  ; where in shadow its period goes
SHLEV   EQU 15                  ; and its level
TMASK   EQU 17                  ; R7 with its tone bit at 0
NMASK   EQU 18                  ; R7 with its noise bit at 0
PRIO    EQU 19                  ; an effect's priority
CHAN    EQU 20                  ; bytes a channel
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; WHERE IT BREAKS. game.asm whose flip places the room's guards a loop late,
; in flip1 instead of flip0.
init:   di
        ld sp, SYS_AREA
        call here               ; page 1's slot ID: this cartridge's (chapter 38)
        call setpage2           ; page 2 shows it too: the second half
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, GAME_R3      ; colours  $2000, one set for three thirds
        VDP_REG 4, GAME_R4      ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $01          ; border black
        VRAM_WRITE SAT          ; no sprites yet
        ld a, $D0
        out (VDP_DATA), a
        ld hl, VARS             ; the variables' page, all 0
        ld de, VARS + 1
        ld bc, 255
        ld (hl), 0
        ldir
        ld hl, names            ; and the copy of the names, the map's page
        ld de, names + 1        ; and the pictures
        ld bc, minis + 16 * 96 - names - 1
        ld (hl), 0
        ldir
        ld hl, ENGINE           ; the player's page, all 0
        ld de, ENGINE + 1
        ld bc, 255
        ld (hl), 0
        ldir
        ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rla
        ld hl, 262              ; 60 Hz ...
        jr nc, .rlines
        ld hl, 313              ; ... and 50 Hz
.rlines:ld (lines), hl
        ld hl, 0
        ld (owed), hl
        ld (beats), hl
        ld a, 1                 ; the first tick reads a row
        ld (tick), a
        xor a
        ld (barno), a
        ld (rowno), a
        ld hl, song - 6         ; the step before the first
        ld (songp), hl
        ld hl, start            ; shadow and the four channels
        ld de, shadow
        ld bc, 91
        ldir
        ld hl, hstart           ; the best to beat
        ld de, hi
        ld bc, 3
        ldir
        call sets               ; the shapes and colours of the three thirds
        VRAM_WRITE SPAT         ; the explorer, patterns 0 to 3, a guard 4 to 7
        ld hl, sprites
        ld bc, 64 << 8 | VDP_DATA
        otir
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        ld a, TITLE
        call go                 ; the first state: title0 ends with EI
        di
        in a, (VDP_CTRL)        ; no signal left over (chapter 39)
        VDP_REG 1, $E2          ; display on, the frame's signal, sprites 16 x 16
main:   ei
frame:  halt                    ; isr: the status kept, the frame counted
woke:   call sends              ; 18  the explorer, the names queued, a page
sent:   call run                ; 18  the state's work
ran:    jr frame                ; 13

; run: this frame's routine for the state held in state.
; go: A = a state -> it is the state, and its start routine has run.
;     Both use every register that routine uses (chapter 41)
run:    ld a, (state)           ; 14
        ld hl, frames           ; 11
        jr table                ; 13
go:     ld (state), a           ; 14
        ld hl, starts           ; 11
table:  add a, a                ;  5  two bytes a state
        add a, l                ;  5
        ld l, a                 ;  5  the tables do not cross a page
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5
        jp (hl)                 ;  5  and its RET goes back to the caller

; isr: every frame. The status kept in stat, the signal let down; the frame
; counted, and its lines owed to the game's steps; the keys and the stick read
; while the frame is young; then chapter 37's player: when pace gives it a
; tick, last tick's registers to the PSG first, then the next tick: at the
; title the tune, and in every other state hush, the sounds alone. Keeps
; every register it uses
isr:    push af                 ; 12
        in a, (VDP_CTRL)        ; 12  the status: F, 5S, C, a sprite's number
        ld (stat), a            ; 14
        push bc                 ; 12
        push de                 ; 12
        push hl                 ; 12
        push ix                 ; 17
        ld hl, (ticks)          ; 17
        inc hl                  ;  7
        ld (ticks), hl          ; 17
        ld hl, (due)            ; 17  the lines owed to the game ...
        ld de, (lines)          ; 22
        add hl, de              ; 12  ... and this frame's, 262 or 313
        ld (due), hl            ; 17
        call input              ; 18  held
        call pace               ; 18  carry: the player's tick (chapter 37)
        jr nc, .done            ; 13, or 8
        call tochip             ; 18
        ld a, (state)           ; 14
        or a                    ;  5  TITLE?
        jr nz, .hush            ; 13, or 8
        call play               ; 18  the tune
        jr .done                ; 13
.hush:  call hush               ; 18  the sounds alone
.done:  pop ix                  ; 16
        pop hl                  ; 11
        pop de                  ; 11
        pop bc                  ; 11
        pop af                  ; 11
isrend: ei                      ;  5
        ret                     ; 11

; hush: a tick with the music silent: the three channels' levels 0, every
; tone and noise shut, and a sound of the game's, if one is sounding, over
; channel C, as play has it. Uses A, BC, DE, HL, IX
hush:   ld a, $BF               ;  8  all shut; bit 7 at 1, bit 6 at 0
        ld hl, shadow + 7       ; 11
        ld (hl), a              ;  8
        xor a                   ;  5
        inc l                   ;  5
        ld (hl), a              ;  8  R8, A's level
        inc l                   ;  5
        ld (hl), a              ;  8  R9, B's
        inc l                   ;  5
        ld (hl), a              ;  8  R10, C's
        ld ix, chan_x           ; 16  a sound?
        ld a, (ix + WAITS)      ; 21  its ticks still to sound
        or a                    ;  5
        ret z                   ; 12, or 6  none
        dec (ix + WAITS)        ; 25
        jp sound                ; 11  whose RET is hush's

; retune: the tune from its first bar, as INIT leaves the player, and no
; sound of the game's: shadow and the four channels from start. The
; interrupts must be off. Uses A, BC, DE, HL
retune: ld a, 1                 ;  8  the first tick reads a row
        ld (tick), a            ; 14
        xor a                   ;  5
        ld (barno), a           ; 14
        ld (rowno), a           ; 14
        ld hl, song - 6         ; 11  the step before the first
        ld (songp), hl          ; 17
        ld hl, start            ; 11  shadow and the four channels
        ld de, shadow           ; 11
        ld bc, 91               ; 11
        ldir                    ; 23 a byte, 18 the last
        ret                     ; 11

; input: in the interrupt, the keys and joystick 1 together (chapters 34
; and 35) -> held, in register 14's way: bits 0 to 3 up, down, left, right,
; bit 4 SPACE or button A, bit 5 M or button B, a 0 for each held. Uses A,
; BC, HL
input:  call keys               ; 18  rows 4 and 8 in register 14's way
        ld c, a                 ;  5
        xor a                   ;  5  port 1
        call joy                ; 18  its register 14
        and c                   ;  5  held on either
        ld (held), a            ; 14
        ret                     ; 11

; keys: rows 4 and 8 of the keyboard -> A in register 14's way: the cursor
; keys as the four switches, SPACE as button A, M as button B, a 0 for each
; held. The interrupts must be off. Uses A, BC, HL
keys:   in a, (PPI_C)           ; 12
        and $F0                 ;  8  port C's top bits kept (chapter 34)
        ld c, a                 ;  5
        or 4                    ;  8
        out (PPI_C), a          ; 12  row 4
        in a, (PPI_B)           ; 12  bit 2: M
        or $FB                  ;  8  M alone
        rlca                    ;  5
        rlca                    ;  5
        rlca                    ;  5  into bit 5, button B's
        ld b, a                 ;  5
        ld a, c                 ;  5
        or 8                    ;  8
        out (PPI_C), a          ; 12  row 8
        in a, (PPI_B)           ; 12  bits 7-4: RIGHT DOWN UP LEFT; bit 0: SPACE
        ld c, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $0F                 ;  8
        ld hl, kbdjoy           ; 11
        add a, l                ;  5
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 1                   ;  8  SPACE
        rlca                    ;  5
        rlca                    ;  5
        rlca                    ;  5
        rlca                    ;  5  into bit 4, button A's
        or (hl)                 ;  8  and the cursor keys as the switches
        or $E0                  ;  8
        and b                   ;  5  and M
        ret                     ; 11

; joy: A = $00 for port 1, $40 for port 2 -> A = that port's register 14, a 0
; for each switch closed. Register 15's other seven bits are kept. The
; interrupts must be off. Uses A, B
joy:    ld b, a                 ;  5
        ld a, 15                ;  8
        out (PSG_ADDR), a       ; 12  register 15
        in a, (PSG_READ)        ; 12  as it is
        and $BF                 ;  8  bit 6: the port
        or b                    ;  5
        out (PSG_WRITE), a      ; 12
        ld a, 14                ;  8
        out (PSG_ADDR), a       ; 12  register 14
        in a, (PSG_READ)        ; 12  the port's pins
        ret                     ; 11

; sends: straight after HALT, before the paper: the sprites' attributes,
; the names the frame before queued, and the whole page if one was left.
; Uses A, BC, DE, HL
sends:  VRAM_WRITE SAT          ; 40
        ld hl, copy             ; 11
        ld bc, 13 << 8 | VDP_DATA ; 11  the explorer, the guards, the end
        otir                    ; 23 a byte, 18 the last
        ld hl, queued           ; 11
        ld a, (hl)              ;  8
        or a                    ;  5
        jr z, .page             ; 13, or 8  none queued
        ld b, a                 ;  5
        ld (hl), 0              ; 11  none from now on
        ld l, low queue         ;  8  the queue in queued's page
.name:  ld a, (hl)              ;  8
        out (VDP_CTRL), a       ; 12
        inc l                   ;  5
        ld a, (hl)              ;  8
        out (VDP_CTRL), a       ; 12  its address
        inc l                   ;  5
        ld a, (hl)              ;  8
        out (VDP_DATA), a       ; 12  and its name
        inc l                   ;  5
        djnz .name              ; 14, or 9
.page:  ld hl, whole            ; 11
        ld a, (hl)              ;  8
        or a                    ;  5
        ret z                   ; 12, or 6  no page
        ld (hl), 0              ; 11
        ld hl, (wsrc)           ; 17
        ld de, (wr3)            ; 22  E: R#3, D: R#4
; show: HL = rows 1 to 23 of a page, E = R#3 and D = R#4 -> the registers
; set and the 736 names sent at 29 T-states a name (chapter 20), from row 1
; down: ahead of the beam, if they start before the paper does. Uses A, BC,
; D, HL
show:   di                      ;  5
        ld a, e                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, $83               ;  8
        out (VDP_CTRL), a       ; 12  R#3
        ld a, d                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, $84               ;  8
        out (VDP_CTRL), a       ; 12  R#4
        VRAM_WRITE $1820        ; 40  row 1
        ei                      ;  5
        ld bc, VDP_DATA         ; 11  B: 0, a run of 256
        ld d, 2                 ;  8  two runs
.run:   outi                    ; 18
        jp nz, .run             ; 11
        dec d                   ;  5
        jr nz, .run             ; 13, or 8
        ld b, 224               ;  8  and 224 more
.end:   outi                    ; 18
        jp nz, .end             ; 11
        ret                     ; 11

; page: HL = rows 1 to 23 of a page of names, E = R#3 and D = R#4 to show it
; with -> all left for the next frame's sends. Uses A
page:   ld (wsrc), hl           ; 17
        ld (wr3), de            ; 22  R#3, then R#4
        ld a, 1                 ;  8
        ld (whole), a           ; 14
        ret                     ; 11

; presses: -> A = the keys held now and not the loop before, a 1 for each;
; was keeps held for the next time. Uses A, B, HL
presses: ld hl, was             ; 11
        ld a, (held)            ; 14
        ld b, (hl)              ;  8  the loop before's
        ld (hl), a              ;  8  and this loop's, for the next
        cpl                     ;  5  a 1 for each held now
        and b                   ;  5  and not then
        ret                     ; 11

; paced: B = the game's steps owed, one for each STEPL lines that isr has
; added to due, which keeps what is left over. Uses B, DE, HL
paced:  ld hl, (due)            ; 17
        ld de, -STEPL           ; 11
        ld b, 0                 ;  8
.more:  add hl, de              ; 12  carry: STEPL lines more
        jr nc, .rest            ; 13, or 8
        inc b                   ;  5  a step
        jr .more                ; 13
.rest:  sbc hl, de              ; 17  the last STEPL given back: no carry
        ld (due), hl            ; 17
        ret                     ; 11

; walk: held -> the explorer two pixels along X for LEFT or RIGHT, then two
; along Y for UP or DOWN, each where walled finds no wall (chapter 39); a
; step past an edge, where only a door lets the explorer stand, goes out:
; the carry, D = the way out. Uses A, BC, DE, HL
walk:   ld bc, (explorer)       ; 22  C = Y, B = X
        ld hl, held             ; 11
        bit 2, (hl)             ; 14  LEFT
        jr nz, .right           ; 13, or 8
        ld d, WAY_W             ;  8
        ld a, b                 ;  5
        or a                    ;  5
        jr z, .out              ; 13, or 8  at the left edge: out
        dec b                   ;  5
        dec b                   ;  5
.right: bit 3, (hl)             ; 14  RIGHT
        jr nz, .x               ; 13, or 8
        ld d, WAY_E             ;  8
        ld a, b                 ;  5
        cp X_LAST               ;  8
        jr z, .out              ; 13, or 8  at the right edge: out
        inc b                   ;  5
        inc b                   ;  5
.x:     push bc                 ; 12
        call walled             ; 18  NZ: a wall there
        pop bc                  ; 11
        jr nz, .y               ; 13, or 8
        ld a, b                 ;  5
        ld (explorer + 1), a    ; 14  the new X
.y:     ld bc, (explorer)       ; 22  X as it is now, and Y
        ld hl, held             ; 11
        bit 0, (hl)             ; 14  UP
        jr nz, .down            ; 13, or 8
        ld d, WAY_N             ;  8
        ld a, c                 ;  5
        cp Y_FIRST              ;  8
        jr z, .out              ; 13, or 8  at the top: out
        dec c                   ;  5
        dec c                   ;  5
.down:  bit 1, (hl)             ; 14  DOWN
        jr nz, .w               ; 13, or 8
        ld d, WAY_S             ;  8
        ld a, c                 ;  5
        cp Y_LAST               ;  8
        jr z, .out              ; 13, or 8  at the bottom: out
        inc c                   ;  5
        inc c                   ;  5
.w:     push bc                 ; 12
        call walled             ; 18
        pop bc                  ; 11
        jr nz, .in              ; 13, or 8  a wall
        ld a, c                 ;  5
        ld (explorer), a        ; 14  the new Y
.in:    or a                    ;  5  no carry: still in the room
        ret                     ; 11
.out:   scf                     ;  5  the carry: out by D's way
        ret                     ; 11

; cell: B = X, C = a line -> HL: the cell of the copy of the names that holds
; the pixel. Keeps BC. Uses A, DE
cell:   ld a, c                 ;  5
        and $F8                 ;  8  the row x 8
        ld l, a                 ;  5
        ld h, 0                 ;  8
        add hl, hl              ; 12
        add hl, hl              ; 12  the row x 32
        ld a, b                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8  the column
        add a, l                ;  5
        ld l, a                 ;  5
        ld de, names            ; 11
        add hl, de              ; 12
        ret                     ; 11

; walled: B = X, C = Y of a ball's place -> NZ if a wall is under any of its
; 16 x 16 pixels: the cells from column X / 8 to (X + 15) / 8 and from row
; (Y + 1) / 8 to (Y + 16) / 8, for a sprite's first line is Y + 1 (chapter
; 26). A wall is any name from the brick's up. Uses A, BC, DE, HL
walled: inc c                   ;  5  the first line
        call cell               ; 18  HL: the cell of the top left pixel
        ld a, b                 ;  5
        and 7                   ;  8
        ld d, 2                 ;  8  two columns on a column's edge,
        jr z, .cols             ; 13, or 8
        inc d                   ;  5  three anywhere else
.cols:  ld a, c                 ;  5
        and 7                   ;  8
        ld e, 2                 ;  8  and two rows, or three
        jr z, .rows             ; 13, or 8
        inc e                   ;  5
.rows:  ld b, d                 ;  5
        push hl                 ; 12
.cell:  ld a, (hl)              ;  8
        cp BRICK                ;  8  the bricks and the letters
        jr nc, .wall            ; 13, or 8
        inc hl                  ;  7
        djnz .cell              ; 14, or 9
        pop hl                  ; 11
        ld bc, 32               ; 11
        add hl, bc              ; 12  the row of cells below
        dec e                   ;  5
        jr nz, .rows            ; 13, or 8
        ret                     ; 11  Z: no wall
.wall:  pop hl                  ; 11
        or a                    ;  5  A is BRICK or more
        ret                     ; 11  NZ: a wall

; leave: D = the way out -> the room on that side, the explorer at its edge
; on the side it comes in by, on the same line or column, and the flip.
; Uses A, DE, HL
leave:  ld a, d                 ;  5
        add a, a                ;  5
        add a, d                ;  5  three bytes a way
        add a, low ways         ;  8
        ld l, a                 ;  5
        ld h, high ways         ;  8  the table in one page
        ld a, (room)            ; 14
        add a, (hl)             ;  8
        ld (room), a            ; 14  the room on that side
        inc l                   ;  5
        ld e, (hl)              ;  8  0 for Y, 1 for X
        inc l                   ;  5
        ld a, (hl)              ;  8  the edge it comes in at
        ld d, 0                 ;  8
        ld hl, explorer         ; 11
        add hl, de              ; 12
        ld (hl), a              ;  8
        ld a, FLIP              ;  8
        jp go                   ; 11

; unpack: A = a room -> its runs, from the table rooms in the cartridge's
; second half, into rows 1 to 23 of the copy of the names. A run is a byte:
; the tile in bits 7 to 5, its cells less one in bits 4 to 0; no run goes
; past the end of a row, so that a run that ends a page of the copy ends a
; row too. Uses A, BC, DE, HL
unpack: add a, a                ;  5  two bytes a room
        ld l, a                 ;  5
        ld h, high rooms        ;  8  the table at the start of a page
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5  HL: the room's runs
        ld de, names + 32       ; 11  DE: row 1 of the copy
.run:   ld a, (hl)              ;  8  a run
        inc hl                  ;  7
        ld c, a                 ;  5
        and 31                  ;  8
        ld b, a                 ;  5
        inc b                   ;  5  B: its cells
        ld a, c                 ;  5
        rlca                    ;  5
        rlca                    ;  5
        rlca                    ;  5
        and 7                   ;  8  A: its tile, the name
.cell:  ld (de), a              ;  8
        inc e                   ;  5  Z: the end of a page of the copy
        djnz .cell              ; 14, or 9
        jr nz, .run             ; 13, or 8
        inc d                   ;  5  the next page
        ld a, d                 ;  5
        cp high (names + 768)   ;  8
        jr nz, .run             ; 13, or 8
        ret                     ; 11  the room's 736 cells

; flip0: THE ROOM CHANGES. Its runs unpacked into the copy of the names, and
; its lanterns that are lit lit there; its name posted for row 0; seen;
; WHERE IT BREAKS: its guards left where they were; the explorer's place kept for
; a touch; and the whole page left for the next frame's sends
flip0:  ld a, (room)            ; 14
        call unpack             ; 18  rows 1 to 23 of the copy
        call lights             ; 18  its lanterns lit
        call rname              ; 18  row 0: its name
        call visit              ; 18
        ld hl, (explorer)       ; 17  Y, then X
        ld (back), hl           ; 17  where it came in
        ld hl, names + 32       ; 11
        ld de, GAME_R4 << 8 | GAME_R3 ; 11
        jp page                 ; 11  for the next sends

; flip1: the page sent: WHERE IT BREAKS, the room's guards at their first
; places only now, and the play again
flip1:  call greset             ; 18  a loop late
        ld a, PLAY              ;  8
        jp go                   ; 11
; rname: the room's name, its column's letter and its row's digit, posted
; for row 0. Uses A, BC, DE, HL
rname:  ld a, (room)            ; 14
        and 3                   ;  8
        add a, 'A'              ;  8
        ld hl, names + ROOM_AT  ; 11
        call post               ; 18
        ld a, (room)            ; 14
        rrca                    ;  5
        rrca                    ;  5
        and 3                   ;  8
        add a, '1'              ;  8
        ld hl, names + ROOM_AT + 1 ; 11
        jp post                 ; 11

; visit: the room seen, and the first time fresh, for play1 to make its
; picture. Uses A, HL
visit:  ld a, (room)            ; 14
        ld hl, been             ; 11
        add a, l                ;  5
        ld l, a                 ;  5  been in one page
        xor a                   ;  5
        ld (fresh), a           ; 14
        or (hl)                 ;  8
        ret nz                  ; 12, or 6  seen before
        inc (hl)                ; 12  seen now
        inc a                   ;  5
        ld (fresh), a           ; 14
        ret                     ; 11

; greset: the room's guards at the start of their rounds, from gtab, twelve
; bytes a room: for each guard its Y and X, then its round. Uses A, BC, DE,
; HL
greset: ld a, (room)            ; 14
        add a, a                ;  5
        add a, a                ;  5
        ld c, a                 ;  5
        add a, a                ;  5
        add a, c                ;  5  twelve bytes a room
        ld l, a                 ;  5
        ld h, high gtab         ;  8  the table at a page's start
        ld de, guard0           ; 11
        ldi                     ; 18
        ldi                     ; 18  guard 0's Y and X
        ld de, gd               ; 11
        ldi                     ; 18
        ldi                     ; 18
        ldi                     ; 18
        ldi                     ; 18  and its round
        ld de, guard1           ; 11
        ldi                     ; 18
        ldi                     ; 18  guard 1's
        ld de, gd + 4           ; 11
        ldi                     ; 18
        ldi                     ; 18
        ldi                     ; 18
        ldi                     ; 18
        ret                     ; 11

; guards: a step of the room's two guards, each on its round. Uses A, BC,
; DE, HL
guards: ld hl, gd               ; 11  guard 0's round
        call patrol             ; 18
        ld hl, gd + 4           ; 11  and guard 1's
; patrol: HL = a guard's round, four bytes: where in the copy its Y or its X
; is, the least, the places of the round and its step -> a step on; a step
; past either end turns it, and it steps the other way instead. Uses A, BC,
; DE, HL
patrol: ld e, (hl)              ;  8  its Y or its X, in the copy's page
        ld d, high copy         ;  8
        inc l                   ;  5
        ld b, (hl)              ;  8  B: the least
        inc l                   ;  5
        ld c, (hl)              ;  8  C: the places, most - least + 1
        inc l                   ;  5  HL: its step
        ld a, (de)              ;  8  where it is
        add a, (hl)             ;  8  a step on
        sub b                   ;  5
        cp c                    ;  5  carry: still on its round
        jr c, .put              ; 13, or 8
        ld a, (hl)              ;  8
        neg                     ; 10
        ld (hl), a              ;  8  the other way
        ex de, hl               ;  5
        add a, (hl)             ;  8  from where it is
        ex de, hl               ;  5
        sub b                   ;  5
.put:   add a, b                ;  5
        ld (de), a              ;  8
        ret                     ; 11

; lights: the room's lanterns that are lit, LIT in the copy of the names.
; Uses A, C, HL
lights: ld a, (room)            ; 14
        add a, a                ;  5  its first lantern's number
        ld c, a                 ;  5
        call .one               ; 18
        inc c                   ;  5  and its second
.one:   ld hl, lit              ; 11
        ld a, l                 ;  5
        add a, c                ;  5
        ld l, a                 ;  5  lit in one page
        ld a, (hl)              ;  8
        or a                    ;  5
        ret z                   ; 12, or 6  not lit
        ld a, c                 ;  5
        add a, a                ;  5
        add a, a                ;  5  four bytes a lantern
        add a, 2                ;  8  the third: its cell
        ld l, a                 ;  5
        ld h, high ltab         ;  8  the table at a page's start
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5
        ld (hl), LIT            ; 11
        ret                     ; 11

; lamps: the room's two lanterns against the explorer, and the keep lit
; when the last is. Uses every register but IY
lamps:  ld a, (room)            ; 14
        add a, a                ;  5
        ld c, a                 ;  5  its first lantern
        call lamp               ; 18
        inc c                   ;  5  and its second
        call lamp               ; 18
        ld a, (nlit)            ; 14
        cp LAMPS                ;  8
        ret nz                  ; 12, or 6
        ld a, WIN               ;  8
        jp go                   ; 11  every lantern lit

; lamp: C = a lantern's number -> lit, if it is not yet and the explorer's
; pixels reach its cell or a pixel round it: its cell LIT, posted; a hundred
; points; one more lit, posted; its sound; and its room lit on the map when
; its other lantern is lit too. Keeps C. Uses A, B, DE, HL, IX
lamp:   ld hl, lit              ; 11
        ld a, l                 ;  5
        add a, c                ;  5
        ld l, a                 ;  5  lit in one page
        ld a, (hl)              ;  8
        or a                    ;  5
        ret nz                  ; 12, or 6  lit already
        ex de, hl               ;  5  DE: its byte in lit
        ld a, c                 ;  5
        add a, a                ;  5
        add a, a                ;  5  four bytes a lantern
        ld l, a                 ;  5
        ld h, high ltab         ;  8
        ld a, (explorer + 1)    ; 14  X
        add a, (hl)             ;  8  X - 8 x its column + 16
        cp 25                   ;  8
        ret nc                  ; 12, or 6  too far left or right
        inc l                   ;  5
        ld a, (explorer)        ; 14  Y, the first line less 1
        add a, (hl)             ;  8  Y + 1 - 8 x its row + 16
        cp 25                   ;  8
        ret nc                  ; 12, or 6  too far up or down
        inc l                   ;  5
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5  HL: its cell in the copy
        ld a, 1                 ;  8
        ld (de), a              ;  8  lit
        push bc                 ; 12
        ld a, LIT               ;  8
        call post               ; 18  its cell, queued
        ld a, $10               ;  8  ten tens
        call addten             ; 18  a hundred points (chapter 44)
        ld a, (nlit)            ; 14
        add a, 1                ;  8
        daa                     ;  5  one more, in BCD
        ld (nlit), a            ; 14
        ld hl, names + LIT_AT   ; 11
        call post2              ; 18  its two digits
        ld a, S_LAMP            ;  8
        call fx                 ; 18  its sound
        pop bc                  ; 11
        ld a, c                 ;  5
        and $FE                 ;  8  the room's first lantern
        ld hl, lit              ; 11
        add a, l                ;  5
        ld l, a                 ;  5
        ld a, (hl)              ;  8
        inc l                   ;  5
        and (hl)                ;  8  NZ: both lit
        ret z                   ; 12, or 6
        ld a, (room)            ; 14
; glow: A = a room -> its twelve names on the map lit. Uses A, BC, DE, HL
glow:   ld hl, glowc            ; 11  a lit room's colours
; colours: A = a room, HL = 96 colours -> its twelve names' colours on the
; map, in its third, at 29 T-states a byte (chapter 20): where the play's
; screen never looks. Uses A, BC, DE, HL
colours: add a, a               ;  5  two bytes a room
        add a, low piccol       ;  8
        ld e, a                 ;  5
        ld d, high piccol       ;  8  the table in one page
        ld a, (de)              ;  8
        di                      ;  5
        out (VDP_CTRL), a       ; 12
        inc e                   ;  5
        ld a, (de)              ;  8
        out (VDP_CTRL), a       ; 12  the address
        ei                      ;  5
        ld bc, 96 << 8 | VDP_DATA ; 11
.byte:  outi                    ; 18
        jp nz, .byte            ; 11
        ret                     ; 11

; dim: a room more of the map back to unlit, one a loop, sixteen in all,
; while the end is shown. Uses A, BC, DE, HL
dim:    ld a, (dimmed)          ; 14
        cp 16                   ;  8
        ret nc                  ; 12, or 6  all sixteen
        inc a                   ;  5
        ld (dimmed), a          ; 14
        dec a                   ;  5
        ld hl, dimc             ; 11  an unlit room's colours
        jr colours              ; 13

; clock: a step of the time: every TICKS steps a unit fewer, its three
; digits posted -> Z when none is left. Uses A, BC, DE, HL
clock:  ld hl, tock             ; 11
        dec (hl)                ; 12
        ret nz                  ; 12, or 6  NZ: no unit yet
        ld (hl), TICKS          ; 11
        ld hl, time + 1         ; 11  the tens and the units
        ld a, (hl)              ;  8
        sub 1                   ;  8
        daa                     ;  5  a unit fewer, in BCD (chapter 9)
        ld (hl), a              ;  8
        dec hl                  ;  7  the hundreds
        ld a, (hl)              ;  8
        sbc a, 0                ;  8  less the borrow
        ld (hl), a              ;  8
        add a, DIGIT0           ;  8
        ld hl, names + TIME_AT  ; 11
        call post               ; 18  its digit
        ld a, (time + 1)        ; 14
        ld hl, names + TIME_AT + 1 ; 11
        call post2              ; 18  and the other two
        ld a, (time)            ; 14
        ld hl, time + 1         ; 11
        or (hl)                 ;  8  Z: 000
        ret                     ; 11

; play0: no steps owed yet, and no keys pressed
play0:  ld hl, 0                ; 11
        ld (due), hl            ; 17
        ld a, (held)            ; 14
        ld (was), a             ; 14
        ret                     ; 11

; play1: THE FRAME OF THE PLAY. A room seen for the first time gets its
; picture for the map, a frame of its own; C, which isr kept from the frame
; the sends before drew, is a guard's touch; M or button B pressed shows the
; map; else, for each step owed, a step of the explorer, out of the room
; when it goes through a door, a step of each guard, and of the time, which
; at none ends the game; then the lanterns the explorer reaches. Uses every
; register but IY
play1:  ld a, (fresh)           ; 14
        or a                    ;  5
        jr z, .look             ; 13, or 8
        call mini               ; 18  its picture
        jp play0                ; 11  and the frame counts as none
.look:  ld a, (stat)            ; 14
        and $20                 ;  8  C: two sprites met
        ld a, HIT               ;  8
        jp nz, go               ; 11  a guard touched the explorer
        call presses            ; 18
        and $20                 ;  8  M or button B
        jr nz, tomap            ; 13, or 8
        call paced              ; 18  B: the steps owed (chapter 44)
.step:  push bc                 ; 12
        call walk               ; 18  carry: out, by D's way
        pop bc                  ; 11
        jp c, leave             ; 11  through a door
        push bc                 ; 12
        call guards             ; 18
        call clock              ; 18  Z: no time left
        pop bc                  ; 11
        jr z, timeup            ; 13, or 8
        djnz .step              ; 14, or 9
        jp lamps                ; 11
timeup: ld a, OVER              ;  8
        jp go                   ; 11
tomap:  ld a, MAP               ;  8
        jp go                   ; 11

; hit0: A TOUCH. A life fewer, posted; its sound; and the game held still
hit0:   ld hl, lives            ; 11
        dec (hl)                ; 12
        ld a, (hl)              ;  8
        add a, DIGIT0           ;  8
        ld hl, names + LIVES_AT ; 11
        call post               ; 18  its digit
        ld a, STILL             ;  8
        ld (left), a            ; 14
        ld a, S_TOUCH           ;  8
        jp fx                   ; 11

; hit1: the steps owed off the wait, and at its end GAME OVER with no lives
; left, or else the explorer back where it came into the room, which is
; flipped again: its guards at their first places
hit1:   call countdown          ; 18
        ret nz                  ; 12, or 6
        ld a, (lives)           ; 14
        or a                    ;  5
        ld a, OVER              ;  8
        jp z, go                ; 11  no lives left
        ld hl, (back)           ; 17
        ld (explorer), hl       ; 17  Y and X
        ld a, FLIP              ;  8
        jp go                   ; 11

; countdown: left less the steps owed, down to 0 -> Z at 0. Uses A, B, DE, HL
countdown: call paced           ; 18  B: the steps owed
        ld hl, left             ; 11
        ld a, (hl)              ;  8
        sub b                   ;  5
        jr nc, .left            ; 13, or 8
        xor a                   ;  5  no less than none
.left:  ld (hl), a              ;  8
        or a                    ;  5
        ret                     ; 11

; over0: GAME OVER: its sound, then the end
over0:  ld a, S_OVER            ;  8
        call fx                 ; 18
        ld hl, obox             ; 11  its box
        jr ending               ; 13

; win0: THE KEEP IS LIT: the time left added to the score, its tens and
; units, then its hundreds; its sound; then the end
win0:   ld a, (time + 1)        ; 14
        call addsc              ; 18  the tens and the units (chapter 40)
        ld a, (time)            ; 14  the hundreds, as tens of tens
        add a, a                ;  5
        add a, a                ;  5
        add a, a                ;  5
        add a, a                ;  5
        call addten             ; 18
        ld a, S_WIN             ;  8
        call fx                 ; 18
        ld hl, wbox             ; 11
; ending: HL = the end's box -> the sprites hidden, hi kept the best, the box
; on the screen with the score and the best, and ENDS steps of it, while
; the map's rooms are unlit again. Uses every register but IY
ending: ld a, $D0               ;  8
        ld (explorer), a        ; 14  the end of the sprites: none shown
        push hl                 ; 12
        call best               ; 18  hi kept the best (chapter 40)
        pop hl                  ; 11
        call box                ; 18
        ld a, ENDS              ;  8
        ld (left), a            ; 14
        xor a                   ;  5
        ld (dimmed), a          ; 14
        ret                     ; 11

; over1: the end's frame, OVER's and WIN's: a room of the map unlit, the
; steps owed off the wait, and at its end the title again
over1:  call dim                ; 18
        call countdown          ; 18
        ret nz                  ; 12, or 6
        ld a, TITLE             ;  8
        jp go                   ; 11

; box: HL = five rows of 24 names -> on the screen at BOX_AT, 29 T-states a
; name (chapter 20); then the score's six digits and the best's. Uses A, BC,
; DE, HL
box:    ld de, BOX_AT | $4000   ; 11
        ld a, 5                 ;  8  five rows
.row:   push af                 ; 12
        di                      ;  5
        ld a, e                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        out (VDP_CTRL), a       ; 12  the row's first cell
        ei                      ;  5
        ld bc, 24 << 8 | VDP_DATA ; 11
.name:  outi                    ; 18
        jp nz, .name            ; 11
        ld a, e                 ;  5
        add a, 32               ;  8  the row below
        ld e, a                 ;  5
        jr nc, .page            ; 13, or 8
        inc d                   ;  5
.page:  pop af                  ; 11
        dec a                   ;  5
        jr nz, .row             ; 13, or 8
        ld hl, score            ; 11
        ld de, SCORE_AT | $4000 ; 11
        call put3               ; 18
        ld hl, hi               ; 11
        ld de, HI_AT | $4000    ; 11
; put3: HL = three BCD bytes, DE = the VRAM address of the first digit, plus
; $4000 -> the six digits sent (chapter 42's putbcd). Uses A, BC, HL
put3:   di                      ;  5
        ld a, e                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        out (VDP_CTRL), a       ; 12
        ei                      ;  5
        ld b, 3                 ;  8
.byte:  ld a, (hl)              ;  8
        call putbcd             ; 18
        inc hl                  ;  7
        djnz .byte              ; 14, or 9
        ret                     ; 11

; mini: the room's picture for the map, from the copy of the names, rows 1
; to 23: a bit a cell, 1 for a wall, eight cells a byte, four bytes a row,
; into minis, and a row of none under them; then sent to its names in its
; third of the VRAM, where the play's screen never looks. Uses every
; register but IY
mini:   xor a                   ;  5
        ld (fresh), a           ; 14  made now
        ld a, (room)            ; 14
        call picat              ; 18  DE: the room's picture in minis
        push de                 ; 12
        ld hl, names + 32       ; 11  the copy's row 1
        ld c, 23 * 4            ;  8  rows 1 to 23, four bytes each
.byte:  DUP 8                   ; sjasmplus writes the next four lines 8 times
        ld a, (hl)              ;  8  a cell
        add a, $100 - BRICK     ;  8  carry: BRICK or more, a wall
        rl b                    ; 10  into the byte
        inc hl                  ;  7
        EDUP
        ld a, b                 ;  5
        ld (de), a              ;  8
        inc de                  ;  7
        dec c                   ;  5
        jr nz, .byte            ; 13, or 8
        xor a                   ;  5  row 24, under the room
        ld b, 4                 ;  8
.none:  ld (de), a              ;  8
        inc de                  ;  7
        djnz .none              ; 14, or 9
        ld a, (room)            ; 14
        add a, a                ;  5  two bytes a room
        add a, low picvram      ;  8
        ld l, a                 ;  5
        ld h, high picvram      ;  8  the table in one page
        ld e, (hl)              ;  8
        inc l                   ;  5
        ld d, (hl)              ;  8  DE: its names' shapes in its third
        pop hl                  ; 11  HL: the picture
; picture: HL = a room's picture in minis, DE = the VRAM address of the
; shapes of its first name, plus $4000 for writing -> its 12 names' 96 bytes
; sent: a name's eight lines are a column of the picture, eight of its
; bytes, four apart. Uses A, BC, DE, HL
picture: di                     ;  5
        ld a, e                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        out (VDP_CTRL), a       ; 12  the address
        ei                      ;  5
        ld c, VDP_DATA          ;  8
        ld e, 3                 ;  8  three rows of names
.rowof: ld d, 4                 ;  8  four names in a row
.name:  push hl                 ; 12  its first line
        ld b, 8                 ;  8  eight lines
.line:  outi                    ; 18
        inc hl                  ;  7
        inc hl                  ;  7
        inc hl                  ;  7  the line below: four bytes on
        jp nz, .line            ; 11
        pop hl                  ; 11
        inc hl                  ;  7  the next name: a byte on
        dec d                   ;  5
        jr nz, .name            ; 13, or 8
        ld a, l                 ;  5
        add a, 32 - 4           ;  8  the next row of names: eight lines on
        ld l, a                 ;  5
        jr nc, .page            ; 13, or 8
        inc h                   ;  5
.page:  dec e                   ;  5
        jr nz, .rowof           ; 13, or 8
        ret                     ; 11

; picat: A = a room -> DE: its picture in minis, 96 bytes a room. Uses A,
; DE, HL
picat:  ld l, a                 ;  5
        ld h, 0                 ;  8
        add hl, hl              ; 12
        add hl, hl              ; 12
        add hl, hl              ; 12
        add hl, hl              ; 12
        add hl, hl              ; 12  x 32
        ld d, h                 ;  5
        ld e, l                 ;  5
        add hl, hl              ; 12  x 64
        add hl, de              ; 12  x 96
        ld de, minis            ; 11
        add hl, de              ; 12
        ex de, hl               ;  5
        ret                     ; 11

; map0: THE MAP. The explorer's Y kept and the explorer hidden, the map's
; page built in mapn and left for the next frame's sends, with a set of
; shapes and colours for each third
map0:   ld a, (explorer)        ; 14
        ld (keepy), a           ; 14
        ld a, $D0               ;  8
        ld (explorer), a        ; 14  the end of the sprites: none shown
        call mapbuild           ; 18
        ld hl, mapn             ; 11
        ld de, MAP_R4 << 8 | MAP_R3 ; 11
        jp page                 ; 11

; map1: M or button B pressed again: the explorer back, the room's page
; left for the next sends, and the play again
map1:   call presses            ; 18
        and $20                 ;  8  M or button B
        ret z                   ; 12, or 6
        ld a, (keepy)           ; 14
        ld (explorer), a        ; 14
        ld hl, names + 32       ; 11
        ld de, GAME_R4 << 8 | GAME_R3 ; 11
        call page               ; 18
        ld a, PLAY              ;  8
        jp go                   ; 11

; mapbuild: the map's 736 names in mapn: its page from the cartridge, then
; for each room seen its 4 x 3 names, the explorer's room's from CURRENT,
; whose shapes in that room's third get its picture now. Uses every
; register but IY
mapbuild: ld hl, mapbase        ; 11  the map's page, in the second half
        ld de, mapn             ; 11
        ld bc, 736              ; 11
        ldir                    ; 23 a byte, 18 the last
        ld c, 0                 ;  8  room 0
.room:  ld hl, been             ; 11
        ld a, l                 ;  5
        add a, c                ;  5
        ld l, a                 ;  5  been in one page
        ld a, (hl)              ;  8
        or a                    ;  5
        jr z, .next             ; 13, or 8  not seen: dark
        ld a, (room)            ; 14
        cp c                    ;  5
        ld b, CURRENT           ;  8
        jr z, .put              ; 13, or 8  the explorer's room
        ld hl, mapnm            ; 11
        ld a, l                 ;  5
        add a, c                ;  5
        ld l, a                 ;  5
        ld b, (hl)              ;  8  B: the room's first name
.put:   ld hl, mapat            ; 11
        ld a, c                 ;  5
        add a, a                ;  5
        add a, l                ;  5
        ld l, a                 ;  5
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5  HL: its first cell in mapn
        call put4               ; 18  its three rows of four names
        call put4               ; 18
        call put4               ; 18
.next:  inc c                   ;  5
        ld a, c                 ;  5
        cp 16                   ;  8
        jr nz, .room            ; 13, or 8
        ld a, (room)            ; 14  the explorer's room's picture, for CURRENT
        call picat              ; 18  DE: in minis
        ld a, (room)            ; 14
        add a, a                ;  5
        add a, low curvram      ;  8
        ld l, a                 ;  5
        ld h, high curvram      ;  8
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5  HL: CURRENT's shapes in its third
        ex de, hl               ;  5
        jp picture              ; 11

; put4: B = a name, HL = a cell of mapn -> B to B + 3 in it and the three
; after it; HL the cell below, B the name after. Uses B, DE, HL
put4:   ld (hl), b              ;  8
        inc hl                  ;  7
        inc b                   ;  5
        ld (hl), b              ;  8
        inc hl                  ;  7
        inc b                   ;  5
        ld (hl), b              ;  8
        inc hl                  ;  7
        inc b                   ;  5
        ld (hl), b              ;  8
        inc b                   ;  5
        ld de, 32 - 3           ; 11
        add hl, de              ; 12  the row below
        ret                     ; 11

; title0: the title's 768 names at 29 T-states a name (chapter 20) and the
; best score in them; the explorer, and a guard on its round; and the tune
; from its first bar
title0: di                      ;  5
        call retune             ; 18  the tune again
        VRAM_WRITE $1800        ; 40
        ei                      ;  5
        ld hl, tnames           ; 11  in the second half
        ld bc, VDP_DATA         ; 11  B: 0, a run of 256; C: the port
        ld d, 3                 ;  8  three runs
.run:   outi                    ; 18
        jp nz, .run             ; 11
        dec d                   ;  5
        jr nz, .run             ; 13, or 8
        ld hl, hi               ; 11
        ld de, THI_AT | $4000   ; 11
        call put3               ; 18  the best's six digits
        ld hl, tcopy            ; 11  the sprites, and the end
        ld de, copy             ; 11
        ld bc, 13               ; 11
        ldir                    ; 23 a byte, 18 the last
        ld hl, tround           ; 11  and the guard's round
        ld de, gd               ; 11
        ld bc, 4                ; 11
        ldir                    ; 23 a byte, 18 the last
        ret                     ; 11

; title1: the guard a step on its round for each step owed; SPACE or button
; A held? A game begins, with the flip into its first room
title1: call paced              ; 18
.step:  push bc                 ; 12
        ld hl, gd               ; 11
        call patrol             ; 18
        pop bc                  ; 11
        djnz .step              ; 14, or 9
        ld a, (held)            ; 14  isr read them
        and $10                 ;  8  SPACE, button A
        ret nz                  ; 12, or 6
pressed: call setup             ; 18  a new game
        ld a, FLIP              ;  8
        jp go                   ; 11

; setup: a new game. No names queued, no rooms seen, no lantern lit; score
; 0, LIVES lives, the time full; the explorer in the gate hall at its first
; place
setup:  xor a                   ;  5
        ld (queued), a          ; 14
        ld (nlit), a            ; 14
        ld hl, been             ; 11  been and lit, 48 bytes
        ld b, 48                ;  8
.none:  ld (hl), a              ;  8
        inc l                   ;  5
        djnz .none              ; 14, or 9
        ld hl, score            ; 11
        ld (hl), a              ;  8
        inc l                   ;  5
        ld (hl), a              ;  8
        inc l                   ;  5
        ld (hl), a              ;  8
        ld a, LIVES             ;  8
        ld (lives), a           ; 14
        ld hl, $9909            ; 11  the hundreds 9, then 99
        ld (time), hl           ; 17
        ld a, TICKS             ;  8
        ld (tock), a            ; 14
        ld a, START             ;  8
        ld (room), a            ; 14
        ld hl, first            ; 11  the explorer's first place
        ld de, copy             ; 11
        ld bc, 4                ; 11
        ldir                    ; 23 a byte, 18 the last
        ret                     ; 11
; sets: the shapes and colours of every name into each third's tables, the
; display off: the tiles, the dark, chapter 30's characters, the colours of
; the rooms' pictures, black on white, and of the explorer's room's, black
; on cyan. Uses A, BC, DE, HL
sets:   ld de, $0000 | $4000    ; 11  third 0's shapes
.third: ld hl, vshapes          ; 11
        call set2k              ; 18
        ld a, d                 ;  5
        add a, $20              ;  8  its colours, $2000 on
        ld d, a                 ;  5
        ld hl, vcolours         ; 11
        call set2k              ; 18
        ld a, d                 ;  5
        sub $20 - 8             ;  8  the next third's shapes, $800 on
        ld d, a                 ;  5
        cp $18 | $40            ;  8
        jr nz, .third           ; 13, or 8
        ret                     ; 11

; set2k: HL = 2,048 bytes, DE = a VRAM address plus $4000 -> sent, with the
; display off. Uses A, BC, HL
set2k:  ld a, e                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        out (VDP_CTRL), a       ; 12  the address
        ld bc, VDP_DATA         ; 11  B: 0, a run of 256
        ld a, 8                 ;  8  eight runs
.run:   otir                    ; 23 a byte, 18 the last
        dec a                   ;  5
        jr nz, .run             ; 13, or 8
        ret                     ; 11
; post: HL = a cell of the copy of the names, A = a name -> the name written
; there and queued for the next frame's sends. Uses A, BC, DE, HL
post:   ld (hl), a              ;  8
        ld c, a                 ;  5  the name
        ld de, ($1800 + $4000 - names) & $FFFF ; 11
        add hl, de              ; 12  its VRAM address, plus $4000 for writing
        ex de, hl               ;  5  in DE
        ld hl, queued           ; 11
        ld a, (hl)              ;  8
        inc (hl)                ; 12  one more
        ld b, a                 ;  5
        add a, a                ;  5
        add a, b                ;  5  three bytes each
        add a, low queue        ;  8
        ld l, a                 ;  5  the queue in queued's page
        ld (hl), e              ;  8
        inc l                   ;  5
        ld (hl), d              ;  8
        inc l                   ;  5
        ld (hl), c              ;  8
        ret                     ; 11
; post2: A = a BCD byte, HL = the cell of its first digit in the copy of the
; names -> its two digits posted. Uses A, BC, DE, HL
post2:  push hl                 ; 12
        push af                 ; 12
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and 15                  ;  8  the first digit
        add a, DIGIT0           ;  8
        call post               ; 18
        pop af                  ; 11
        pop hl                  ; 11
        inc hl                  ;  7  the next cell
        and 15                  ;  8  the second
        add a, DIGIT0           ;  8
        jp post                 ; 11

; addten: A = points in tens, two BCD digits -> added to score: its second
; digit to the tens, its first to the hundreds, the carry taken on with ADC
; and DAA (chapter 9). Uses A, BC, HL
addten: ld c, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and 15                  ;  8  the first digit, as hundreds
        ld b, a                 ;  5
        ld a, c                 ;  5
        add a, a                ;  5
        add a, a                ;  5
        add a, a                ;  5
        add a, a                ;  5  the second, as tens
        ld hl, score + 2        ; 11  the tens and the units
        add a, (hl)             ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        dec hl                  ;  7  the thousands and the hundreds
        ld a, b                 ;  5
        adc a, (hl)             ;  8  with the tens' carry
        daa                     ;  5
        ld (hl), a              ;  8
        dec hl                  ;  7  and the first two digits
        ld a, (hl)              ;  8
        adc a, 0                ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        ret                     ; 11

; fx: A = a sound -> chapter 37's sfx, with the interrupts off, for sfx and
; the player share chan_x. Uses A, DE, HL, IX
fx:     di                      ;  5
        call sfx                ; 18
        ei                      ;  5
        ret                     ; 11

; best: score against hi, the first digits first -> hi is score when score
; is higher. Uses A, BC, DE, HL
best:   ld hl, score            ; 11
        ld de, hi               ; 11
        ld b, 3                 ;  8  three bytes
.byte:  ld a, (de)              ;  8  a byte of hi
        cp (hl)                 ;  8  less the same byte of score
        jr c, .new              ; 13, or 8  score's is higher: a new best
        ret nz                  ; 12, or 6  hi's is higher
        inc l                   ;  5
        inc e                   ;  5  the same: the next byte decides
        djnz .byte              ; 14, or 9
        ret                     ; 11  the same number
.new:   ld c, b                 ;  5  the bytes from here on, this one too;
        ld b, 0                 ;  8  the ones before are the same
        ldir                    ; 23, and 18 the last time
        ret                     ; 11

; addsc: A = points, two BCD digits -> added to score, the carry taken into
; the digits before with ADC and DAA (chapter 9). Uses A, HL
addsc:  ld hl, score + 2        ; 11  the last two digits
        add a, (hl)             ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        dec l                   ;  5  DEC L leaves the carry alone
        ld a, (hl)              ;  8
        adc a, 0                ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        dec l                   ;  5
        ld a, (hl)              ;  8
        adc a, 0                ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        ret                     ; 11

; putbcd: A = a BCD byte, the VRAM address set -> its two digits sent, as
; the patterns from DIGIT0 (chapter 40's, with an OR). Uses A, C
putbcd: ld c, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5  the first digit to bits 3 to 0
        and $0F                 ;  8
        or DIGIT0               ;  8  its pattern
        out (VDP_DATA), a       ; 12
        ld a, c                 ;  5
        and $0F                 ;  8  the second digit
        or DIGIT0               ;  8
        out (VDP_DATA), a       ; 12
        ret                     ; 11

; here: -> A = the slot ID of page 1, where INIT runs: the primary slot from
; port $A8 and, if EXPTBL says it is expanded, the secondary from the
; slot's own register. The interrupts must be off. Uses A, BC, HL
here:   in a, (PPI_A)           ; 12
        rrca                    ;  5
        rrca                    ;  5
        and 3                   ;  8  page 1's primary slot
        ld c, a                 ;  5
        ld b, 0                 ;  8
        ld hl, EXPTBL           ; 11
        add hl, bc              ; 12
        or (hl)                 ;  8  bit 7 if the slot is expanded
        ret p                   ; 12, or 6  it is not: that is the ID
        ld l, a                 ;  5  1000 00PP
        and 3                   ;  8
        call subreg             ; 18  the slot's register
        and %00001100           ;  8  page 1's secondary slot
        or l                    ;  5
        ret                     ; 11

; setpage2: A = a slot ID -> page 2 shows that slot: its primary slot in
; port $A8 and, for an expanded slot, its secondary slot in the slot's
; register, written at $FFFF through page 3 and copied into SLTTBL for the
; BIOS. The interrupts must be off. Uses A, BC, DE, HL
setpage2: ld e, a               ;  5  the slot ID
        and 3                   ;  8
        rrca                    ;  5
        rrca                    ;  5
        ld d, a                 ;  5  the primary slot in bits 6-7
        rrca                    ;  5
        rrca                    ;  5
        ld b, a                 ;  5  and in bits 4-5
        in a, (PPI_A)           ; 12
        ld c, a                 ;  5  the slots as they are
        bit 7, e                ; 10  expanded?
        jr z, .primary          ; 13, or 8
        and $3F                 ;  8
        or d                    ;  5
        out (PPI_A), a          ; 12  page 3 shows the slot: no RAM
        ld a, (SSLOT)           ; 14
        cpl                     ;  5  its register, as it stands
        and %11001111           ;  8  page 2's secondary slot cleared
        ld d, a                 ;  5
        ld a, e                 ;  5
        and %00001100           ;  8  the new one, in bits 2-3
        rlca                    ;  5
        rlca                    ;  5  and in bits 4-5
        or d                    ;  5
        ld (SSLOT), a           ; 14  written
        ld d, a                 ;  5
        ld a, c                 ;  5
        out (PPI_A), a          ; 12  page 3 back: the RAM again
        ld a, e                 ;  5
        and 3                   ;  8
        add a, low SLTTBL       ;  8
        ld l, a                 ;  5
        ld h, high SLTTBL       ;  8
        ld (hl), d              ;  8  SLTTBL for that slot, as the BIOS keeps it
.primary: ld a, c               ;  5
        and %11001111           ;  8  page 2's primary slot cleared
        or b                    ;  5  and set
        out (PPI_A), a          ; 12
        ret                     ; 11

; subreg: A = an expanded primary slot -> A = its secondary slot register,
; read at $FFFF through page 3, which hands it back complemented. The
; interrupts must be off: while page 3 shows that slot the RAM is gone, and
; the stack with it. Uses A, B, C
subreg: rrca                    ;  5
        rrca                    ;  5  the slot into bits 6-7
        ld b, a                 ;  5
        in a, (PPI_A)           ; 12
        ld c, a                 ;  5  the slots as they are
        and $3F                 ;  8
        or b                    ;  5
        out (PPI_A), a          ; 12  page 3 shows the slot: no RAM
        ld a, (SSLOT)           ; 14  its register, complemented
        cpl                     ;  5
        ld b, a                 ;  5
        ld a, c                 ;  5
        out (PPI_A), a          ; 12  page 3 back: the RAM again
        ld a, b                 ;  5
        ret                     ; 11

; pace: carry if the player ticks in this frame. Its ticks are 313 lines
; apart, a frame of the 50 Hz machine: each frame adds its own lines to
; owed, and a tick pays 313 of them back. Uses DE, HL
pace:   ld hl, (owed)           ; 17
        ld de, (lines)          ; 22  313 or 262, from INIT
        add hl, de              ; 12
        ld de, -313             ; 11
        add hl, de              ; 12  carry: 313 lines are owed
        jr c, .paid             ; 13, or 8
        sbc hl, de              ; 17  not yet: the 313 given back, no carry
.paid:  ld (owed), hl           ; 17
        ret                     ; 11

; tochip: R0 to R10 from shadow, in order. Uses A, BC, HL
tochip: ld hl, shadow           ; 11
        ld bc, 11 << 8 | PSG_WRITE ; 11  B: the registers; C: the port
        xor a                   ;  5  R0 first
.reg:   out (PSG_ADDR), a       ; 12  the register
        inc a                   ;  5
        outi                    ; 18  its byte; HL on, and B down
        jr nz, .reg             ; 13, or 8
        ret                     ; 11

; play: the next tick into shadow: every SPEED ticks a row of each channel,
; then each channel's level, period and mixer bits, and an effect, if one
; is sounding, over channel C. Uses A, BC, DE, HL, IX
play:   ld hl, (beats)          ; 17  one tick more
        inc hl                  ;  7
        ld (beats), hl          ; 17
        ld hl, tick             ; 11
        dec (hl)                ; 12
        jr nz, .sounds          ; 13, or 8
        ld (hl), SPEED          ; 11  a row
        ld hl, rowno            ; 11
        inc (hl)                ; 12  next sets it to 0 at a new bar
        ld ix, chan_a           ; 16
        call row                ; 18
        ld ix, chan_b           ; 16
        call row                ; 18
        ld ix, chan_c           ; 16
        call row                ; 18
.sounds: ld a, $BF              ;  8  all shut; bit 7 at 1, bit 6 at 0
        ld (shadow + 7), a      ; 14
        ld ix, chan_a           ; 16
        call sound              ; 18
        ld ix, chan_b           ; 16
        call sound              ; 18
        ld ix, chan_c           ; 16
        call sound              ; 18
        ld ix, chan_x           ; 16  an effect?
        ld a, (ix + WAITS)      ; 21  its ticks still to sound
        or a                    ;  5
        ret z                   ; 12, or 6  none: channel C is the music's
        dec (ix + WAITS)        ; 25
        ld a, (shadow + 7)      ; 14  the music's tone and noise on C shut
        or %00100100            ;  8
        ld (shadow + 7), a      ; 14
        jp sound                ; 11  the effect's, whose RET is play's

; row: IX = a channel -> a row: one less to wait, and at none, its pattern's
; next event, and its instrument's tables from their first byte. Uses A,
; BC, DE, HL
row:    dec (ix + WAITS)        ; 25
        ret nz                  ; 12, or 6
        ld l, (ix + PATTERN)    ; 21
        ld h, (ix + PATTERN + 1) ; 21
        ld a, (hl)              ;  8
        inc hl                  ;  7
        cp END                  ;  8  the pattern's end?
        jr nz, .event           ; 13, or 8
        call next               ; 18  the song's next step
        ld a, (hl)              ;  8
        inc hl                  ;  7
.event: bit 7, a                ; 10  an instrument first?
        jr z, .note             ; 13, or 8
        and $7F                 ;  8
        ld (ix + INSTR), a      ; 21
        ld a, (hl)              ;  8
        inc hl                  ;  7
.note:  ld (ix + NOTE), a       ; 21  0 for a rest
        ld a, (hl)              ;  8  the rows it lasts
        inc hl                  ;  7
        ld (ix + WAITS), a      ; 21
        ld (ix + PATTERN), l    ; 21
        ld (ix + PATTERN + 1), h ; 21

; voice: IX = a channel -> its instrument's two tables from their first
; byte, its mixer bits and its noise's period, from instruments, 6 bytes
; each. Leaves the carry clear. Uses A, DE, HL
voice:  ld a, (ix + INSTR)      ; 21
        ld l, a                 ;  5
        add a, a                ;  5
        add a, l                ;  5  three times
        add a, a                ;  5  six times
        ld l, a                 ;  5
        ld h, 0                 ;  8
        ld de, instruments      ; 11
        add hl, de              ; 12  no carry: the table is in the ROM
        ld a, (hl)              ;  8  the volume table
        ld (ix + VOLUME), a     ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + VOLUME + 1), a ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the pitch table
        ld (ix + PITCHES), a    ; 21
        ld (ix + FIRST), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + PITCHES + 1), a ; 21
        ld (ix + FIRST + 1), a  ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the mixer's bits
        ld (ix + MIXER), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the noise's period
        ld (ix + NOISEP), a     ; 21
        ret                     ; 11

; next: the song's next step, or its first after the last: each channel's
; new pattern, and IX's in HL; the bar counted, and its row 0. Uses A, BC,
; DE, HL
next:   ld hl, (songp)          ; 17
        ld de, 6                ; 11
        add hl, de              ; 12
        ld a, (hl)              ;  8
        inc hl                  ;  7
        or (hl)                 ;  8  a word 0: the end
        dec hl                  ;  7
        ld a, (barno)           ; 14
        jr nz, .keep            ; 13, or 8
        ld hl, song             ; 11  the first step again
        xor a                   ;  5
.keep:  inc a                   ;  5
        ld (barno), a           ; 14
        ld (songp), hl          ; 17
        xor a                   ;  5
        ld (rowno), a           ; 14
        ld de, chan_a + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld de, chan_b + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld de, chan_c + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld l, (ix + PATTERN)    ; 21
        ld h, (ix + PATTERN + 1) ; 21
        ret                     ; 11

; sound: IX = a channel -> its level, and for a note its period, in
; shadow, its tables a tick on; its tone and noise opened in R7, and R6
; its noise's period. Uses A, BC, DE, HL
sound:  ld c, 0                 ;  8  a rest's level
        ld a, (ix + NOTE)       ; 21
        or a                    ;  5
        jr z, .level            ; 13, or 8
        ld l, (ix + VOLUME)     ; 21
        ld h, (ix + VOLUME + 1) ; 21
        ld a, (hl)              ;  8  this tick's level
        cp END                  ;  8  the table's end?
        jr nz, .vstep           ; 13, or 8
        dec hl                  ;  7  the last level again
        ld c, (hl)              ;  8
        jr .pitch               ; 13
.vstep: ld c, a                 ;  5
        inc hl                  ;  7
        ld (ix + VOLUME), l     ; 21
        ld (ix + VOLUME + 1), h ; 21
.pitch: ld l, (ix + PITCHES)    ; 21
        ld h, (ix + PITCHES + 1) ; 21
        ld a, (hl)              ;  8  this tick's semitones
        cp LOOP                 ;  8
        jr nz, .hold            ; 13, or 8
        ld l, (ix + FIRST)      ; 21  the first again
        ld h, (ix + FIRST + 1)  ; 21
        ld a, (hl)              ;  8
        jr .pstep               ; 13
.hold:  cp HOLD                 ;  8
        jr nz, .pstep           ; 13, or 8
        dec hl                  ;  7  the last again
        ld a, (hl)              ;  8
        jr .pnote               ; 13
.pstep: inc hl                  ;  7
        ld (ix + PITCHES), l    ; 21
        ld (ix + PITCHES + 1), h ; 21
.pnote: add a, (ix + NOTE)      ; 21  the note they move it to
        add a, a                ;  5
        ld l, a                 ;  5
        ld h, high notes        ;  8  its period, in a page of its own
        ld e, (hl)              ;  8
        inc l                   ;  5
        ld d, (hl)              ;  8
        ld l, (ix + SHPER)      ; 21
        ld h, (ix + SHPER + 1)  ; 21
        ld (hl), e              ;  8
        inc hl                  ;  7
        ld (hl), d              ;  8
.level: ld l, (ix + SHLEV)      ; 21
        ld h, (ix + SHLEV + 1)  ; 21
        ld (hl), c              ;  8
        ld b, (ix + MIXER)      ; 21
        ld a, (shadow + 7)      ; 14
        bit 0, b                ; 10  a tone?
        jr z, .noise            ; 13, or 8
        and (ix + TMASK)        ; 21
.noise: bit 1, b                ; 10  a noise?
        jr z, .mixer            ; 13, or 8
        and (ix + NMASK)        ; 21
        ld (shadow + 7), a      ; 14
        ld a, (ix + NOISEP)     ; 21
        ld (shadow + 6), a      ; 14
        ret                     ; 11
.mixer: ld (shadow + 7), a      ; 14
        ret                     ; 11

; sfx: A = an effect -> it starts on channel C, unless the effect still
; sounding has a higher priority: then carry, and nothing changes. The
; interrupts must be off. Uses A, DE, HL, IX
sfx:    add a, a                ;  5
        add a, a                ;  5  4 bytes an effect
        ld e, a                 ;  5
        ld d, 0                 ;  8
        ld hl, effects          ; 11
        add hl, de              ; 12  its priority, instrument, note, ticks
        ld ix, chan_x           ; 16
        ld a, (ix + WAITS)      ; 21  an effect sounding?
        or a                    ;  5
        ld a, (hl)              ;  8  the new one's priority
        jr z, .take             ; 13, or 8  none
        cp (ix + PRIO)          ; 21
        ret c                   ; 12, or 6  lower: refused
.take:  ld (ix + PRIO), a       ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the instrument, $80 and its number
        and $7F                 ;  8
        ld (ix + INSTR), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + NOTE), a       ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + WAITS), a      ; 21  the ticks it sounds
        jp voice                ; 11  its tables, and no carry
codeend:                        ; the code ends here
        ALIGN 16
